      "key": "p3-65-67",
      "bodyEn": "Woman: Mr. Panganiban, the quarterly channel numbers are in. Anything jump out at you?\nMan: 【1】The farmers markets. We send two staff out there every single Saturday.\nWoman: I've thought the same thing. 【2】But it's how a lot of people first taste our coffee.\nMan: Sure, but we could put those two people behind the cafe counter instead.\nWoman: 【3】Ms. Marwaha will want data before she signs off on pulling out.\nMan: 【4】Then let me build a one-page comparison for her by Friday.\nWoman: Do that, and I'll pull the staffing costs for you.",
