      "bodyEn": "Quintal Storage — 【1】Now Open in Nethercliff\n\nAre you running out of room for your inventory? Quintal Storage rents clean, climate-controlled units in three sizes, starting at €62 per month. Our staff 【2】will §131§ help you select the size that fits your business, and every rental includes access to our loading dock.\n\nGround-floor units are ideal for companies that §132§ deliveries 【3】several times a week. §133§, customers who 【4】sign a full-year agreement pay nothing for their final two weeks.\n\nStop by our Nethercliff office this month and 【5】a member of our team will show you the facility. §134§",
      "bodyJp": "クインタル・ストレージ — 【1】ネザークリフに新規オープン\n\n在庫の置き場所が足りなくなっていませんか。クインタル・ストレージは、清潔で空調管理の行き届いた3サイズの区画を、月額62ユーロからで貸し出しています。当社のスタッフが【2】、お客様の事業に合ったサイズを§131§選ぶお手伝いをいたします。どの契約にも荷さばき場のご利用が含まれます。\n\n1階の区画は、荷物を【3】週に何度も§132§会社に最適です。§133§、通年契約を【4】結ばれたお客様は、最後の2週間分の料金がかかりません。\n\n今月ネザークリフの事務所にお立ち寄りいただければ、【5】当社スタッフが施設をご案内いたします。§134§",
