      "bodyEn": "Padderton (11 May)—Cragmont Builders 【1】has begun converting the town's empty grain hall into space for as many as twelve small shops. The company expects the work to be §139§ by early next year.\n\n§140§ two years, 【2】the hall has stood empty, and rain has damaged part of its roof. According to Ms. Lucia Montalvo, the project architect, 【3】the brick walls and tall windows will be repaired rather than replaced. §141§\n\nMr. Etienne Dubois, who runs Sorrelgate Cafe nearby, welcomed the plan. He said that a §142§ increase in foot traffic would help every business on the street.",
      "bodyJp": "パダートン(5月11日)——Cragmont Builders社が、町の空いた穀物倉庫を最大12軒の小規模店舗が入るスペースへと改装する工事に【1】着手した。同社は、来年初めまでにこの工事が§139§と見込んでいる。\n\n§140§2年間、【2】その倉庫は空き家のままで、雨が屋根の一部を傷めてきた。プロジェクトの建築士であるLucia Montalvoさんによれば、【3】れんが造りの壁と縦長の窓は、取り替えるのではなく補修されるという。§141§\n\n近くでSorrelgate Cafeを営むEtienne Duboisさんは、この計画を歓迎した。彼は、来客数の§142§増加が通りのあらゆる店の助けになるだろうと述べた。",
