      "key": "p7-151-153",
      "bodyEn": "NOTICE -- Attention Lanthorn Museum Guides and Volunteers\n\nBeginning 4 October, the east wing will close while the Calverstoke Textile Collection is rehoused in new climate-controlled cases. -- [1] -- 【1】Tours that normally end in the east wing will finish in the sculpture court instead, and each guide should add roughly ten minutes of walking time to the standard route.\n\nWe expect visitor numbers to rise once the collection reopens, because 【2】several pieces have never been displayed publicly. -- [2] -- For that reason, 【3】we are extending Saturday guide shifts from four hours to six. -- [3] -- Volunteers who cannot take the longer shift should tell the desk before 20 September so that pairs can be rearranged.\n\nPrinted route maps in the guides' room are being replaced this week. -- [4] -- Please discard any copy dated before September; the old maps still show the east wing as open.\n\nMr. Kwame Owusu\nVolunteer Coordinator, Lanthorn Museum",
      "bodyJp": "お知らせ -- ランソーン博物館のガイドおよびボランティアの皆様へ\n\n10月4日より、カルバーストーク織物コレクションを新しい温湿度管理ケースへ移設するため、東翼を閉鎖します。 -- [1] -- 【1】通常は東翼で終わるツアーは、代わりに彫刻ホールで終了することになります。各ガイドは標準ルートに歩行時間を約10分追加してください。\n\nコレクションが再開されれば来館者数は増える見込みです。というのも、【2】いくつかの作品はこれまで一般公開されたことがないからです。 -- [2] -- そのため、【3】土曜日のガイド勤務を4時間から6時間へ延長します。 -- [3] -- 延長勤務に対応できないボランティアは、ペアを組み直せるよう、9月20日までに受付へお知らせください。\n\nガイド室にある印刷版のルートマップは今週差し替えます。 -- [4] -- 9月より前の日付のものはすべて破棄してください。古いマップでは東翼がまだ開いている状態で示されています。\n\nクワメ・オウス\nボランティア・コーディネーター、ランソーン博物館",
