      "bodyEn": "Store Operations Lead -- Tannerly Outfitters, Uppingdon\n\nTannerly Outfitters operates five hiking and camping gear stores across the region. We are seeking a Store Operations Lead for our Uppingdon location, 【2】opening 11 May.\n\nResponsibilities\n- Supervise a team of nine sales associates and two stockroom staff\n- Track inventory and place weekly orders with regional suppliers\n- Resolve customer questions about equipment rentals\n\nRequirements\n- 【1】Three years of retail experience, one of them in a supervisory role\n- Familiarity with inventory software; formal training will be provided\n- Availability on weekends during the summer season\n\nSalary is 34,000 pounds annually, 【3】with a review after six months. Applicants must submit a resume and one professional reference to Ms. Marisol Arellano by 3 April.\n\nwww.tannerlyoutfitters.co/careers",
      "bodyJp": "店舗運営リーダー募集 -- タナリー・アウトフィッターズ、アッピンドン店\n\nタナリー・アウトフィッターズは、この地域でハイキング・キャンプ用品店を5店舗運営しています。当社は、【2】5月11日に開店するアッピンドン店の店舗運営リーダーを募集しています。\n\n職務内容\n- 販売スタッフ9名と在庫管理スタッフ2名からなるチームを監督する\n- 在庫を管理し、地域の仕入れ業者に毎週発注する\n- 用具レンタルに関する顧客からの質問に対応する\n\n応募要件\n- 【1】小売業での3年間の経験。うち1年は管理職としての経験があること\n- 在庫管理ソフトウェアの知識があること(正式な研修は当社が実施します)\n- 夏季シーズン中の週末に勤務できること\n\n給与は年額34,000ポンドで、【3】6か月後に見直しがあります。応募者は、履歴書と職務上の推薦人1名を、4月3日までにマリソル・アレラーノ(Ms. Marisol Arellano)宛てに提出してください。\n\nwww.tannerlyoutfitters.co/careers",
