      "key": "p7-163-165",
      "bodyEn": "Palgrave Financial Trust — Regional Managers' Meeting\nKirtlefield Office, 14 March\n\n8:30 A.M.–9:00 A.M. | Registration and Coffee — Lower Atrium\n【1】Badges must be collected here; the lifts to the meeting rooms will not operate without one.\n\n9:00 A.M.–10:15 A.M. | Lending After the Merger — Mr. Haruki Tomioka\n【2】A review of the branch lending targets that took effect in January.\n\n10:30 A.M.–11:45 A.M. | Reading the Quarterly Dashboard — Ms. Grace Obuya\n【3】Hands-on practice with the reporting tool. Attendees should bring a laptop.\n\n12:00 P.M.–1:00 P.M. | 【5】Lunch — Riverside Room\n\n1:00 P.M.–2:30 P.M. | Client Conversations That Work — Dr. Priya Kulkarni\nA workshop on handling difficult questions from account holders. 【4】Space is limited to twenty-four.\n\nSessions run in the order listed; recordings will be posted to the staff portal by 21 March.",
      "bodyJp": "パルグレイヴ・ファイナンシャル・トラスト — 地区マネージャー会議\nカートルフィールド・オフィス、3月14日\n\n午前8:30〜午前9:00 | 受付とコーヒー — ロウアー・アトリウム\n【1】バッジはここで受け取ること。バッジがないと会議室へのエレベーターは動作しません。\n\n午前9:00〜午前10:15 | 合併後の融資 — トミオカ・ハルキ氏\n【2】1月に発効した支店の融資目標の見直し。\n\n午前10:30〜午前11:45 | 四半期ダッシュボードの読み方 — グレース・オブヤ氏\n【3】レポーティングツールを使った実践演習。参加者はノートパソコンを持参してください。\n\n正午12:00〜午後1:00 | 【5】昼食 — リバーサイド・ルーム\n\n午後1:00〜午後2:30 | 成果につながる顧客との対話 — プリヤ・クルカルニ博士\n口座保有者からの難しい質問への対応に関するワークショップ。【4】定員は24名までです。\n\nセッションは記載の順に進行します。録画は3月21日までにスタッフポータルに掲載されます。",
