      "key": "p7-168-171",
      "bodyEn": "Corriveau Logistics — Dispatch Channel\n\nRosa Malapitan [9:35 A.M.]: The Ivelford depot just told me 【1】the two refrigerated trailers we booked for Thursday are being pulled for inspection. We have the Winnowfield Farms load that morning.\n\nDaniel Paik [9:37 A.M.]: Pulled for how long? Half a day, or the whole week?\n\nRosa Malapitan [9:38 A.M.]: They would not commit. Best case is Thursday afternoon.\n\nMai Yagisawa [9:40 A.M.]: The farm's produce cannot sit past ten. That is not really a schedule question.\n\nDaniel Paik [9:41 A.M.]: 【2】Sennadale has three reefers idle. It is ninety minutes further out, so their drivers would have to leave at five.\n\nMai Yagisawa [9:42 A.M.]: I can ask Sennadale, but 【3】Thursday is already their long run.\n\nRosa Malapitan [9:43 A.M.]: Ask anyway. Someone should also find out whether the inspection can be moved to Friday.\n\nDaniel Paik [9:44 A.M.]: 【4】I will ring the depot manager now. He owes me one.\n\nMai Yagisawa [9:46 A.M.]: 【5】If both of those fail, we tell the farm today, not Wednesday night.\n\nRosa Malapitan [9:47 A.M.]: Agreed. Let us regroup at noon.",
      "bodyJp": "コリヴォー・ロジスティクス — 配車チャンネル\n\nRosa Malapitan [午前9:35]: Ivelfordのデポから今しがた連絡があって、【1】木曜に押さえていた冷蔵トレーラー2台が検査で引き上げられることになった。あの朝はWinnowfield Farmsの積荷があるのに。\n\nDaniel Paik [午前9:37]: どれくらい引き上げられるって? 半日か、それとも一週間まるごと?\n\nRosa Malapitan [午前9:38]: 向こうは確約してくれなかった。よくて木曜の午後。\n\nMai Yagisawa [午前9:40]: 農場の作物は10時を過ぎたら置いておけない。これはもう日程調整の問題じゃないわ。\n\nDaniel Paik [午前9:41]: 【2】Sennadaleに冷蔵車が3台遊んでいる。あそこは90分遠いから、ドライバーは5時に出発しないといけないが。\n\nMai Yagisawa [午前9:42]: Sennadaleに頼んでみることはできるけど、【3】木曜はもともとあそこの長距離便の日なのよ。\n\nRosa Malapitan [午前9:43]: それでも頼んでみて。それと誰か、検査を金曜に動かせないかも確かめて。\n\nDaniel Paik [午前9:44]: 【4】これからデポの責任者に電話してみる。彼には貸しがあるんだ。\n\nMai Yagisawa [午前9:46]: 【5】その両方がだめだったら、水曜の夜じゃなくて今日のうちに農場に伝えましょう。\n\nRosa Malapitan [午前9:47]: 賛成。正午にまた集まりましょう。",
