      "key": "p7-186-190",
      "bodyEn": "[DOCUMENT 1]\nGravenhurst Institute — Autumn Skills Workshops\n\nPikewell Campus | 9:00 A.M. to 4:30 P.M.\n\nEvery workshop fee covers printed materials, 【1】lunch, and a certificate of completion. Each session is limited to 18 participants.\n\nReading Financial Statements — Thursday, 12 November — £145\n【2】Negotiating Supplier Contracts — Thursday, 19 November — £160\nPresenting to Senior Managers — Thursday, 26 November — £135\n【3】Managing Remote Teams — Thursday, 3 December — £150\n\n【4】Participants who enrol in two or more workshops pay £25 less for each one. Enrolment closes ten days before the workshop date. Register at www.gravenhurstinstitute.org/autumn.\n\n[DOCUMENT 2]\nGravenhurst Institute — Workshop Registration Form\n\nName: Ms. Priya Ranganathan\nOrganisation: Gritstone Aggregates\nPosition: Purchasing Supervisor\nDate submitted: 2 November\nWorkshops selected: Negotiating Supplier Contracts; Managing Remote Teams\nDietary requirements: None\nHow did you hear about us? 【5】A colleague attended last spring\nInvoice to: Accounts Department, Gritstone Aggregates, Yaverbridge\nTelephone: 217-555-0176\nAdditional notes: I will arrive by train and may be a few minutes late.\nSignature: P. Ranganathan\n\n[DOCUMENT 3]\nE-mail\n\nTo: Ms. Priya Ranganathan\nFrom: Nadia Rifai, Gravenhurst Institute\nDate: 5 November\nSubject: Change to your autumn enrolment\n\nDear Ms. Ranganathan,\n\nThank you for registering. I am writing about one of the sessions you selected. Because only nine people have enrolled, 【6】we have moved the 19 November session to Thursday, 21 January. Your place has been transferred automatically, and no further action is needed unless you wish to withdraw.\n\nYour other selection, Managing Remote Teams, is unaffected and 【7】will run on the advertised date.\n\n【8】I have also adjusted your invoice, as the reduced rate for multiple enrolments still applies to you. The Accounts Department at Gritstone Aggregates will receive the revised figure this week.\n\nSincerely,\n\nNadia Rifai\nProgramme Coordinator, Gravenhurst Institute",
      "bodyJp": "[DOCUMENT 1]\nGravenhurst Institute — 秋のスキル・ワークショップ\n\nPikewellキャンパス | 午前9時00分〜午後4時30分\n\nすべてのワークショップ受講料には、印刷教材、【1】昼食、修了証が含まれます。各セッションの定員は18名です。\n\n財務諸表の読み方 — 11月12日(木) — £145\n【2】仕入先との契約交渉 — 11月19日(木) — £160\n上級管理職へのプレゼンテーション — 11月26日(木) — £135\n【3】リモートチームのマネジメント — 12月3日(木) — £150\n\n【4】2つ以上のワークショップに申し込む参加者は、それぞれ£25の割引が受けられます。申し込みはワークショップ開催日の10日前に締め切ります。お申し込みは www.gravenhurstinstitute.org/autumn まで。\n\n[DOCUMENT 2]\nGravenhurst Institute — ワークショップ登録フォーム\n\n氏名: Priya Ranganathanさん\n所属組織: Gritstone Aggregates\n役職: 購買主任\n提出日: 11月2日\n選択したワークショップ: 仕入先との契約交渉、リモートチームのマネジメント\n食事に関する要望: なし\n当機関を何でお知りになりましたか? 【5】同僚が昨春参加しました\n請求書送付先: 経理部、Gritstone Aggregates、Yaverbridge\n電話番号: 217-555-0176\n備考: 電車で参りますので、数分遅れる可能性があります。\n署名: P. Ranganathan\n\n[DOCUMENT 3]\nEメール\n\n宛先: Priya Ranganathanさん\n差出人: Nadia Rifai、Gravenhurst Institute\n日付: 11月5日\n件名: 秋の受講登録の変更について\n\nRanganathanさま\n\nお申し込みありがとうございます。お選びいただいたセッションの一つについてご連絡いたします。申込者が9名のみのため、【6】11月19日のセッションを1月21日(木)に移動いたしました。お席は自動的に振り替えられておりますので、キャンセルをご希望でない限り、これ以上のお手続きは不要です。\n\nもう一方でお選びいただいたリモートチームのマネジメントには影響がなく、【7】告知どおりの日程で実施されます。\n\n【8】また、複数受講の割引料金が引き続き適用されますので、請求書も調整いたしました。Gritstone Aggregatesの経理部には、今週中に修正後の金額が届きます。\n\n敬具\n\nNadia Rifai\nプログラム・コーディネーター、Gravenhurst Institute",
