      "key": "p7-191-195",
      "bodyEn": "[DOCUMENT 1]\nwww.nettlecombegardens.org/membership\n\nHome | Visit | Membership | Events | Contact Us\n\nMembership at Nettlecombe Gardens, Marlbeck\n\nSeedling — $45 — 【1】Unlimited entry for one adult.\nCutting — $80 — Unlimited entry for two adults, plus 10 percent off in the shop.\nRootstock — $130 — 【2】Unlimited entry for two adults and up to three children, plus 15 percent off in the shop and two guest passes each year.\nCanopy — $220 — All Rootstock benefits, plus 【3】early entry on event days and a reserved parking space.\n\nMembers at every level may borrow hand tools from the Potting Shed at no charge. 【4】Memberships renew on the anniversary of purchase, and a reminder is sent 21 days beforehand.\n\n[DOCUMENT 2]\nE-mail\n\nTo: members@nettlecombegardens.org\nFrom: c.phumipat@feltonbypost.net\nDate: 8 May\nSubject: Renewal question\n\nDear Membership Office,\n\nMy renewal reminder arrived last week, and I would like to change my level 【5】before it processes on 29 May.\n\nMy circumstances have changed. My partner and I now visit together, and we bring our two nephews most weekends, so I need a level that admits children. We rarely stay for evening events, and I cycle to the Gardens, so a parking space would be of no use to me. The shop discount would be welcome, as I buy many seed trays.\n\n【6】Could you also confirm that the tools I borrowed in March were received? I left them at the Potting Shed on a Sunday, when no one was there to sign.\n\nSincerely,\n\nChai Phumipat\n\n[DOCUMENT 3]\nNettlecombe Gardens — Invoice 5188\n\nBill to: Mr. Chai Phumipat, Feltonby\nInvoice date: 30 May\n\n【7】Annual membership renewal — $130.00\nGuest passes issued (2) — $0.00\n【8】Shop purchase, 12 May: seed trays — $34.50\nMember discount applied (15 percent) — -$5.18\nSubtotal — $159.32\nPostage and handling — $4.00\nTotal due — $163.32\n\nPayment received in full on 30 May. This membership runs until 29 May of next year. Questions? Contact the Membership Office.",
      "bodyJp": "[DOCUMENT 1]\nwww.nettlecombegardens.org/membership\n\nホーム | 来園案内 | 会員制度 | イベント | お問い合わせ\n\nMarlbeck、ネトルコム・ガーデンズの会員制度\n\nシードリング — 45ドル — 【1】大人1名の入場無制限。\nカッティング — 80ドル — 大人2名の入場無制限、加えて店舗で10パーセント割引。\nルートストック — 130ドル — 【2】大人2名および子供3名までの入場無制限、加えて店舗で15パーセント割引と年2枚のゲストパス。\nキャノピー — 220ドル — ルートストックの全特典に加え、【3】イベント開催日の早期入場と専用駐車スペース。\n\n全レベルの会員は、ポッティング・シェッドから手工具を無料で借りられます。【4】会員資格は購入日の記念日に更新され、その21日前にリマインダーが送られます。\n\n[DOCUMENT 2]\nEメール\n\n宛先: members@nettlecombegardens.org\n差出人: c.phumipat@feltonbypost.net\n日付: 5月8日\n件名: 更新についての質問\n\n会員事務局 御中\n\n先週、更新のリマインダーが届きました。【5】5月29日に処理される前に、会員レベルを変更したいと思います。\n\n私の事情が変わりました。今はパートナーと一緒に訪れ、たいていの週末には2人の甥も連れて行くので、子供が入場できるレベルが必要です。夜のイベントに残ることはめったになく、庭園へは自転車で通っているので、駐車スペースは私には無用です。シードトレイを多く買うので、店舗割引はありがたいです。\n\n【6】また、3月に借りた工具が受領されたか確認していただけますか。日曜日にポッティング・シェッドに置いてきたのですが、その時はサインをしてくれる人が誰もいませんでした。\n\n敬具\n\nChai Phumipat\n\n[DOCUMENT 3]\nネトルコム・ガーデンズ — 請求書 5188\n\n請求先: Chai Phumipat様、Feltonby\n請求日: 5月30日\n\n【7】年間会員資格の更新 — 130.00ドル\n発行されたゲストパス（2枚） — 0.00ドル\n【8】店舗購入、5月12日: シードトレイ — 34.50ドル\n会員割引適用（15パーセント） — -5.18ドル\n小計 — 159.32ドル\n送料および手数料 — 4.00ドル\n請求額合計 — 163.32ドル\n\n5月30日に全額の支払いを受領しました。この会員資格は翌年の5月29日まで有効です。ご質問は会員事務局までお問い合わせください。",
